// Local-LLM extraction. The model is asked for NUMBERS ONLY (no names, no free text), and the
// result is validated before use. Summary text is generated by code (summarize.ts), so the
// model never gets a chance to write PII into anything that leaves the private zone.

export interface Extraction {
  /** YYYY-MM the statement period ends in */
  periodEnd: string;
  endingBalance: number;
  totalIn: number;
  totalOut: number;
  upcomingBillsCount: number;
  upcomingBillsTotal: number;
}

const SCHEMA = {
  type: 'object',
  properties: {
    periodEnd: { type: 'string', description: 'Statement period end as YYYY-MM' },
    endingBalance: { type: 'number' },
    totalIn: { type: 'number', description: 'Sum of all deposits/credits in the period, positive' },
    totalOut: { type: 'number', description: 'Sum of all withdrawals/debits in the period, positive' },
    upcomingBillsCount: { type: 'integer' },
    upcomingBillsTotal: { type: 'number' },
  },
  required: ['periodEnd', 'endingBalance', 'totalIn', 'totalOut', 'upcomingBillsCount', 'upcomingBillsTotal'],
} as const;

const PROMPT = `You extract numbers from a bank or card statement. Reply with JSON only, matching the schema.
Never include names, account numbers, addresses, merchants or any other text — only the requested fields.
If a value is not present, use 0. Amounts are plain numbers without currency symbols.`;

export function validateExtraction(raw: unknown): Extraction {
  const o = raw as Record<string, unknown>;
  const num = (k: string): number => {
    const v = o?.[k];
    if (typeof v !== 'number' || !Number.isFinite(v)) throw new Error(`field ${k} is not a finite number`);
    return v;
  };
  // Models often answer with a full date; keep only year-month, but still reject anything else.
  const periodEnd = typeof o?.periodEnd === 'string' ? o.periodEnd.replace(/^(\d{4}-\d{2})-\d{2}$/, '$1') : undefined;
  if (periodEnd === undefined || !/^\d{4}-(0[1-9]|1[0-2])$/.test(periodEnd)) {
    throw new Error('periodEnd must be YYYY-MM');
  }
  const out: Extraction = {
    periodEnd,
    endingBalance: num('endingBalance'),
    totalIn: num('totalIn'),
    totalOut: num('totalOut'),
    upcomingBillsCount: Math.max(0, Math.round(num('upcomingBillsCount'))),
    upcomingBillsTotal: num('upcomingBillsTotal'),
  };
  if (out.totalIn < 0 || out.totalOut < 0 || out.upcomingBillsTotal < 0) throw new Error('negative flow totals');
  return out;
}

export interface OllamaOpts {
  url: string;
  model: string;
  fetch?: typeof fetch;
}

export async function extractFromText(text: string, opts: OllamaOpts): Promise<Extraction> {
  const res = await (opts.fetch ?? fetch)(`${opts.url}/api/chat`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({
      model: opts.model,
      stream: false,
      think: false,
      keep_alive: '30s', // unload soon after use: the Mac mini has to share RAM
      format: SCHEMA,
      options: { temperature: 0 },
      messages: [
        { role: 'system', content: PROMPT },
        { role: 'user', content: text.slice(0, 60_000) },
      ],
    }),
    signal: AbortSignal.timeout(10 * 60_000),
  });
  if (!res.ok) throw new Error(`ollama HTTP ${res.status}`);
  const body = (await res.json()) as { message?: { content?: string } };
  return validateExtraction(JSON.parse(body.message?.content ?? ''));
}
